@layer components {
  :where([data-control-family="stepper"][data-slot="root"]) {
    --stepper-indicator-radius: 9999px;
    --stepper-indicator-background: var(--background);
    --stepper-indicator-foreground: var(--muted-foreground);
    --stepper-indicator-border-color: var(--border);
    --stepper-separator-background: var(--border);
    --stepper-title-foreground: var(--foreground);
  }
  :where([data-control-family="stepper"][data-slot="trigger"]) {
    border-radius: var(--radius-control);
    outline: none;
    transition: color var(--duration-fast) var(--ease-standard);
  }

  :where([data-control-family="stepper"][data-slot="trigger"]:focus-visible) {
    box-shadow: 0 0 0 2px var(--background), 0 0 0 4px var(--ring);
  }

  :where([data-control-family="stepper"][data-slot="trigger"]:disabled) {
    opacity: 0.5;
  }

  :where([data-control-family="stepper"][data-slot="indicator"]) {
    --_stepper-indicator-shadow: 0 0 transparent;
    border: 1px solid var(--stepper-indicator-border-color);
    border-radius: var(--stepper-indicator-radius);
    background: var(--stepper-indicator-background);
    color: var(--stepper-indicator-foreground);
    box-shadow: var(--_stepper-indicator-shadow);
    font-size: var(--text-caption);
    transition-property: color, background-color, border-color, box-shadow;
    transition-duration: var(--duration-base);
    transition-timing-function: var(--ease-standard);
  }

  :where([data-control-family="stepper"][data-slot="indicator"][data-state="complete"]:not([data-invalid])) {
    --stepper-indicator-background: var(--primary);
    --stepper-indicator-foreground: var(--primary-foreground);
    --stepper-indicator-border-color: var(--primary);
  }

  :where([data-control-family="stepper"][data-slot="indicator"][data-state="current"]:not([data-invalid])) {
    --stepper-indicator-foreground: var(--primary-text);
    --stepper-indicator-border-color: var(--primary);
    --_stepper-indicator-shadow: 0 0 0 4px oklch(from var(--primary) l c h / 0.1);
  }

  :where([data-control-family="stepper"][data-slot="indicator"][data-invalid]) {
    --stepper-indicator-background: oklch(from var(--destructive) l c h / 0.1);
    --stepper-indicator-foreground: var(--destructive-text);
    --stepper-indicator-border-color: var(--destructive);
    --_stepper-indicator-shadow: 0 0 transparent;
    border-style: dashed;
  }

  :where([data-control-family="stepper"][data-slot="separator"]) {
    background: var(--stepper-separator-background);
    transition: background-color var(--duration-base) var(--ease-standard);
  }

  :where([data-control-family="stepper"][data-slot="separator"][data-state="complete"]:not([data-invalid])) {
    --stepper-separator-background: var(--primary);
  }

  :where([data-control-family="stepper"][data-slot="title"]) {
    color: var(--stepper-title-foreground);
    font-size: var(--text-body);
  }

  :where([data-control-family="stepper"][data-slot="description"]) {
    color: var(--muted-foreground);
    font-size: var(--text-body);
  }

  :where([data-control-family="stepper"][data-slot="content"]) {
    outline: none;
  }

  :where([data-control-family="stepper"][data-slot="description"]) {
    line-height: var(--leading-relaxed);
  }

  :where([data-control-family="stepper"][data-slot="title"]) {
    font-weight: var(--font-weight-medium);
    line-height: var(--leading-tight);
  }

  :where([data-control-family="stepper"][data-slot="indicator"]) {
    font-weight: var(--font-weight-semibold);
  }

  :where([data-control-family="stepper"][data-slot="trigger"]) {
    --_stepper-trigger-text-align: left;
    text-align: var(--_stepper-trigger-text-align);
  }

  @container stepper (width < 28rem) {
    :where([data-control-family="stepper"][data-slot="trigger"]) {
      --_stepper-trigger-text-align: left;
      text-align: var(--_stepper-trigger-text-align);
    }
  }

  :where([data-control-family="stepper"][data-slot="indicator"]) {
    --_stepper-indicator-number-style: tabular-nums;
    font-variant-numeric: var(--_stepper-indicator-number-style);
  }
}

@property --stepper-indicator-radius {
  syntax: "<length-percentage>";
  inherits: true;
  initial-value: 0px;
}

@property --stepper-indicator-background {
  syntax: "<color>";
  inherits: true;
  initial-value: transparent;
}

@property --stepper-indicator-foreground {
  syntax: "<color>";
  inherits: true;
  initial-value: transparent;
}

@property --stepper-indicator-border-color {
  syntax: "<color>";
  inherits: true;
  initial-value: transparent;
}

@property --stepper-separator-background {
  syntax: "<color>";
  inherits: true;
  initial-value: transparent;
}

@property --stepper-title-foreground {
  syntax: "<color>";
  inherits: true;
  initial-value: transparent;
}

"use client";

import { CheckIcon, CircleAlertIcon } from "lucide-react";
import { createContext, useContext, useId, useState } from "react";
import type {
  StepperContentMode,
  StepperContentProps,
  StepperDescriptionProps,
  StepperIndicatorProps,
  StepperItemProps,
  StepperListProps,
  StepperOrientation,
  StepperProps,
  StepperSeparatorProps,
  StepperState,
  StepperTitleProps,
  StepperTriggerProps,
} from "@/components/control-ui/contracts";
import { cn } from "@/components/control-ui/lib/cn";

type StepperContextValue = {
  value: number | null;
  orientation: StepperOrientation;
  contentMode: StepperContentMode;
  responsive: boolean;
  baseId: string;
  selectStep: (step: number) => void;
};

const StepperContext = createContext<StepperContextValue | null>(null);

function useStepper() {
  const context = useContext(StepperContext);
  if (!context) throw new Error("Stepper parts must be used within <Stepper>.");
  return context;
}

type StepperItemContextValue = {
  step: number;
  state: StepperState;
  disabled: boolean;
  invalid: boolean;
  titleId: string;
  contentId: string;
};

const StepperItemContext = createContext<StepperItemContextValue | null>(null);

function useStepperItem() {
  const context = useContext(StepperItemContext);
  if (!context) throw new Error("Stepper item parts must be used within <StepperItem>.");
  return context;
}

function stateForStep(value: number | null, step: number): StepperState {
  if (value === null) return "neutral";
  if (step < value) return "complete";
  if (step === value) return "current";
  return "upcoming";
}

function indicatorStateLabel(state: StepperState, invalid: boolean): string | null {
  if (invalid) return "invalid";
  if (state === "neutral") return null;
  return state;
}

function defaultIndicatorContent(step: number, state: StepperState, invalid: boolean) {
  if (invalid) return <CircleAlertIcon className="size-4" />;
  if (state === "complete") return <CheckIcon className="size-4" />;
  return step + 1;
}

function itemLayout(orientation: StepperOrientation, responsive: boolean) {
  if (orientation === "vertical") {
    return "grid min-w-0 grid-cols-[2rem_minmax(0,1fr)] pb-6 last:pb-0";
  }
  return cn(
    "relative grid min-w-0 flex-1 grid-cols-1 justify-items-center",
    responsive &&
      "@max-md/stepper:w-full @max-md/stepper:flex-none @max-md/stepper:grid-cols-[2rem_minmax(0,1fr)] @max-md/stepper:justify-items-stretch @max-md/stepper:pb-6 @max-md/stepper:last:pb-0",
  );
}

function partLayout(orientation: StepperOrientation, responsive: boolean, part: "indicator" | "title" | "description") {
  const vertical = {
    indicator: "col-start-1 row-span-2 row-start-1",
    title: "col-start-2 row-start-1 ml-3",
    description: "col-start-2 row-start-2 ml-3",
  }[part];
  if (orientation === "vertical") return vertical;

  const horizontal = {
    indicator: "col-start-1 row-start-1",
    title: "col-start-1 row-start-2 mt-2",
    description: "col-start-1 row-start-3 mt-0.5",
  }[part];
  if (!responsive) return horizontal;

  const narrow = {
    indicator: "@max-md/stepper:col-start-1 @max-md/stepper:row-span-2 @max-md/stepper:row-start-1",
    title: "@max-md/stepper:col-start-2 @max-md/stepper:row-start-1 @max-md/stepper:mt-0 @max-md/stepper:ml-3",
    description: "@max-md/stepper:col-start-2 @max-md/stepper:row-start-2 @max-md/stepper:mt-0 @max-md/stepper:ml-3",
  }[part];
  return cn(horizontal, narrow);
}

export function Stepper({
  value,
  defaultValue = null,
  onValueChange,
  orientation = "horizontal",
  contentMode = "current",
  responsive = true,
  id,
  className,
  children,
  ...props
}: StepperProps) {
  const generatedId = useId();
  const [internalValue, setInternalValue] = useState<number | null>(defaultValue);
  const controlled = value !== undefined;
  const currentValue = value !== undefined ? value : internalValue;

  const selectStep = (step: number) => {
    if (!controlled) setInternalValue(step);
    onValueChange?.(step);
  };

  return (
    <StepperContext.Provider
      value={{
        value: currentValue,
        orientation,
        contentMode,
        responsive,
        baseId: id ?? generatedId,
        selectStep,
      }}
    >
      <div
        {...props}
        id={id}
        data-control-ui="stepper"
        data-control-family="stepper"
        data-slot="root"
        data-orientation={orientation}
        data-content-mode={contentMode}
        data-responsive={responsive ? "true" : undefined}
        className={cn(responsive && "@container/stepper", "w-full", className)}
      >
        {children}
      </div>
    </StepperContext.Provider>
  );
}

export function StepperList({ className, ...props }: StepperListProps) {
  const { orientation, responsive } = useStepper();
  return (
    <ol
      {...props}
      data-control-ui="stepper"
      data-control-family="stepper"
      data-slot="list"
      data-orientation={orientation}
      className={cn(
        orientation === "horizontal" ? "flex w-full items-start" : "flex w-full flex-col",
        orientation === "horizontal" && responsive && "@max-md/stepper:flex-col @max-md/stepper:items-stretch",
        className,
      )}
    />
  );
}

export function StepperItem({ step, disabled = false, invalid = false, className, children, ...props }: StepperItemProps) {
  const { value, orientation, responsive, baseId } = useStepper();
  const state = stateForStep(value, step);
  const contextValue = {
    step,
    state,
    disabled,
    invalid,
    titleId: `${baseId}-step-${step}-title`,
    contentId: `${baseId}-step-${step}-content`,
  } satisfies StepperItemContextValue;

  return (
    <StepperItemContext.Provider value={contextValue}>
      <li
        {...props}
        data-control-ui="stepper"
        data-control-family="stepper"
        data-slot="item"
        data-step={step}
        data-state={state}
        data-disabled={disabled ? "true" : undefined}
        data-invalid={invalid ? "true" : undefined}
        aria-current={state === "current" ? "step" : undefined}
        className={cn("relative", itemLayout(orientation, responsive), className)}
      >
        {children}
      </li>
    </StepperItemContext.Provider>
  );
}

export function StepperTrigger({ disabled: disabledProp, className, onClick, type = "button", ...props }: StepperTriggerProps) {
  const { orientation, responsive, selectStep } = useStepper();
  const { step, state, disabled, invalid, contentId } = useStepperItem();
  const isDisabled = disabled || Boolean(disabledProp);

  return (
    <button
      {...props}
      data-control-ui="stepper"
      data-control-family="stepper"
      data-slot="trigger"
      data-state={state}
      data-invalid={invalid ? "true" : undefined}
      type={type}
      disabled={isDisabled}
      aria-controls={contentId}
      className={cn(
        "group/stepper-trigger col-span-full row-span-3 row-start-1 grid w-full min-w-0 grid-cols-1 justify-items-center disabled:pointer-events-none disabled:cursor-not-allowed",
        orientation === "vertical" && "row-span-2 grid-cols-[2rem_minmax(0,1fr)] justify-items-stretch",
        orientation === "horizontal" &&
          responsive &&
          "@max-md/stepper:row-span-2 @max-md/stepper:grid-cols-[2rem_minmax(0,1fr)] @max-md/stepper:justify-items-stretch",
        className,
      )}
      onClick={(event) => {
        onClick?.(event);
        if (!event.defaultPrevented && !isDisabled) selectStep(step);
      }}
    />
  );
}

export function StepperIndicator({ className, children, ...props }: StepperIndicatorProps) {
  const { orientation, responsive } = useStepper();
  const { step, state, disabled, invalid } = useStepperItem();
  const stateLabel = indicatorStateLabel(state, invalid);
  const status = [`Step ${step + 1}`, stateLabel, disabled ? "disabled" : null].filter(Boolean).join(", ");
  const indicatorContent = children ?? defaultIndicatorContent(step, state, invalid);

  return (
    <span
      {...props}
      data-control-ui="stepper"
      data-control-family="stepper"
      data-slot="indicator"
      data-state={state}
      data-invalid={invalid ? "true" : undefined}
      className={cn(
        "relative z-10 flex size-8 shrink-0 items-center justify-center",
        partLayout(orientation, responsive, "indicator"),
        className,
      )}
    >
      <span aria-hidden="true">{indicatorContent}</span>
      <span className="sr-only">{status}</span>
    </span>
  );
}

export function StepperSeparator({ className, ...props }: StepperSeparatorProps) {
  const { orientation, responsive } = useStepper();
  const { state, invalid } = useStepperItem();
  return (
    <span
      {...props}
      data-control-ui="stepper"
      data-control-family="stepper"
      data-slot="separator"
      data-state={state}
      data-invalid={invalid ? "true" : undefined}
      aria-hidden="true"
      className={cn(
        "absolute",
        orientation === "horizontal" && "top-4 right-[calc(-50%+1rem)] left-[calc(50%+1rem)] h-px",
        orientation === "vertical" && "top-8 bottom-0 left-4 w-px",
        orientation === "horizontal" &&
          responsive &&
          "@max-md/stepper:top-8 @max-md/stepper:right-auto @max-md/stepper:bottom-0 @max-md/stepper:left-4 @max-md/stepper:h-auto @max-md/stepper:w-px",
        className,
      )}
    />
  );
}

export function StepperTitle({ className, ...props }: StepperTitleProps) {
  const { orientation, responsive } = useStepper();
  const { titleId } = useStepperItem();
  return (
    <span
      {...props}
      id={titleId}
      data-control-ui="stepper"
      data-control-family="stepper"
      data-slot="title"
      className={cn("min-w-0", partLayout(orientation, responsive, "title"), className)}
    />
  );
}

export function StepperDescription({ className, ...props }: StepperDescriptionProps) {
  const { orientation, responsive } = useStepper();
  return (
    <span
      {...props}
      data-control-ui="stepper"
      data-control-family="stepper"
      data-slot="description"
      className={cn("min-w-0", partLayout(orientation, responsive, "description"), className)}
    />
  );
}

export function StepperContent({ step, keepMounted = true, className, ...props }: StepperContentProps) {
  const { value, contentMode, baseId } = useStepper();
  const active = value === step;
  const hidden = contentMode === "current" && !active;
  if (hidden && !keepMounted) return null;

  return (
    <section
      {...props}
      id={`${baseId}-step-${step}-content`}
      data-control-ui="stepper"
      data-control-family="stepper"
      data-slot="content"
      data-state={active ? "active" : "inactive"}
      hidden={hidden}
      aria-labelledby={`${baseId}-step-${step}-title`}
      className={cn("mt-6", className)}
    />
  );
}
